// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(this));
        uint256 before = c.currentBetLimit();
        vm.prank(caller);
        try c.AdjustBetAmounts(amount) { } catch { }
        uint256 afterCall = c.currentBetLimit();
        assertTrue(afterCall == before);
    }
}
